//! Controls for the video interface hardware.
//!
//! The role of this module is to display the external framebuffers (XFB) generated by GX.
//! It is agnostic of buffering strategy, so any strategy such as double- or
//! triple-buffering can be used.
//! 
//! The primary features of the video subsystem are:
//! * support for NTSC, PAL, and EURGB60 video formats,
//! * support for interlaced, non-interlaced, and progressive scan modes,
//! * positioning and horizontal scaling of the image onto the TV screen,
//! * an average of 2 bytes per pixel in the XFB via the 4:2:2 YCbCr YUV format.
//! 
//! Unless stated otherwise, "framebuffer" here refers to the *external* framebuffer, as
//! that is what the video module operates on. The embedded framebuffer is managed by GX
//! and is not directly accessible.

use core::sync::atomic::{AtomicPtr, Ordering};
use core::{convert::TryFrom, ffi::c_void, ptr};
use num_enum::TryFromPrimitive;

use crate::utils::Buf32;
use crate::ffi;

/// Function to call before or after a retrace.
pub type RetraceCallback = Option<fn(u32)>;

/// Multiplier to get real pixel size in bytes.
pub const DISPLAY_PIX_SZ: u32 = ffi::VI_DISPLAY_PIX_SZ;
pub const MAX_HEIGHT_DEBUG: u16 = ffi::VI_MAX_HEIGHT_DEBUG as u16;
pub const MAX_HEIGHT_EURGB60: u16 = ffi::VI_MAX_HEIGHT_EURGB60 as u16;
pub const MAX_HEIGHT_MPAL: u16 = ffi::VI_MAX_HEIGHT_MPAL as u16;
pub const MAX_HEIGHT_NTSC: u16 = ffi::VI_MAX_HEIGHT_NTSC as u16;
pub const MAX_HEIGHT_PAL: u16 = ffi::VI_MAX_HEIGHT_PAL as u16;
pub const MAX_WIDTH_DEBUG: u16 = ffi::VI_MAX_WIDTH_DEBUG as u16;
pub const MAX_WIDTH_EURGB60: u16 = ffi::VI_MAX_WIDTH_EURGB60 as u16;
pub const MAX_WIDTH_MPAL: u16 = ffi::VI_MAX_WIDTH_MPAL as u16;
pub const MAX_WIDTH_NTSC: u16 = ffi::VI_MAX_WIDTH_NTSC as u16;
pub const MAX_WIDTH_PAL: u16 = ffi::VI_MAX_WIDTH_PAL as u16;

/// Some colors in YUYV format.
/// 
/// These can be used in [`clear_framebuffer()`] by casting to a `u32`, such as
/// `YuyvColor::Black as u32`. To use a custom color, refer to the 4:2:2 YCbCr equation for
/// converting an RGB color to this color format.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum YuyvColor {
    Black = ffi::COLOR_BLACK,
    Maroon = ffi::COLOR_MAROON,
    Green = ffi::COLOR_GREEN,
    Olive = ffi::COLOR_OLIVE,
    Navy = ffi::COLOR_NAVY,
    Purple = ffi::COLOR_PURPLE,
    Teal = ffi::COLOR_TEAL,
    Gray = ffi::COLOR_GRAY,
    Silver = ffi::COLOR_SILVER,
    Red = ffi::COLOR_RED,
    Lime = ffi::COLOR_LIME,
    Yellow = ffi::COLOR_YELLOW,
    Blue = ffi::COLOR_BLUE,
    Fuchsia = ffi::COLOR_FUCHSIA,
    Aqua = ffi::COLOR_AQUA,
    MoneyGreen = ffi::COLOR_MONEYGREEN,
    SkyBlue = ffi::COLOR_SKYBLUE,
    Cream = ffi::COLOR_CREAM,
    MedGray = ffi::COLOR_MEDGRAY,
    White = ffi::COLOR_WHITE,
}

/// Denotes video format standards for different regions.
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum VideoFmt {
    /// Used in North America and Japan. Has a refresh rate of 60 Hz, or 60 fields per
    /// second.
    Ntsc = ffi::VI_NTSC,
    /// Used in Europe. Has a refresh rate of 50 Hz, or 50 fields per second.
    Pal = ffi::VI_PAL,
    /// Similar to NTSC, used in Brazil
    Mpal = ffi::VI_MPAL,
    /// Debug mode for NA / JPN. Special decoder needed.
    Debug = ffi::VI_DEBUG,
    /// Debug mode for EU. Special decoder needed.
    DebugPal = ffi::VI_DEBUG_PAL,
    /// RGB 60Hz, 480 lines (same timing + aspect as NTSC) used in Europe
    EuRgb60 = ffi::VI_EURGB60,
}

/// How the display image is refreshed
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum ScanMode {
    /// Refreshes the lower video field, then the upper field.
    Interlace = ffi::VI_INTERLACE,
    /// Refreshes only one video field every frame, leaving the other field black. Twice
    /// the refresh rate of interlace, but at half the vertical resolution.
    NonInterlace = ffi::VI_NON_INTERLACE,
    /// Both fields get refreshed every frame.
    Progressive = ffi::VI_PROGRESSIVE,
}

/// Specifies the set of scan lines (AKA the video field) of the framebuffer.
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum VideoField {
    /// Odd-numbered scan lines (1, 3, 5, ...)
    Lower = ffi::VI_FIELD_BELOW,
    /// Even-numbered scan lines (0, 2, 4, ...)
    Upper = ffi::VI_FIELD_ABOVE,
}

/// Whether the framebuffer is in single-field or double-field mode
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum FieldMode {
    Single = ffi::VI_XFBMODE_SF,
    Double = ffi::VI_XFBMODE_DF,
}

/// Video and render settings
#[derive(Debug, Clone, Copy)]
pub struct RenderConfig {
    pub video_fmt: VideoFmt,
    pub scan_mode: ScanMode,
    /// Width of the framebuffer. This is the same between the embedded and external
    /// framebuffers.
    pub fb_width: u16,
    /// Height of the embedded framebuffer
    pub efb_height: u16,
    /// Height of the external framebuffer
    pub xfb_height: u16,
    /// X-coordinate of the first pixel on the screen
    pub vi_origin_x: u16,
    /// Y-coordinate of the first pixel on the screen
    pub vi_origin_y: u16,
    /// Width of the image on the screen in pixels
    pub vi_width: u16,
    /// Height of the image on the screen in pixels
    pub vi_height: u16,
    pub xfb_mode: FieldMode,
    /// Whether field rendering is enabled
    pub field_rendering: bool,
    /// If `None`, anti-aliasing is disabled. Otherwise, specifies the sample pattern to
    /// be used for anti-aliasing. Valid range is 1 - 11 inclusive.
    pub sample_pattern: Option<[[u8; 2]; 12]>,
    /// Vertical filter coefficients. Valid coefficient range is 0 - 63 inclusive; sum
    /// should equal 64.
    pub v_filter: [u8; 7],
}

impl From<RenderConfig> for ffi::GXRModeObj {
    fn from(cfg: RenderConfig) -> ffi::GXRModeObj {
        ffi::GXRModeObj {
            viTVMode: (cfg.video_fmt as u32) << 2 | cfg.scan_mode as u32,
            fbWidth: cfg.fb_width,
            efbHeight: cfg.efb_height,
            xfbHeight: cfg.xfb_height,
            viXOrigin: cfg.vi_origin_x,
            viYOrigin: cfg.vi_origin_y,
            viWidth: cfg.vi_width,
            viHeight: cfg.vi_height,
            xfbMode: cfg.xfb_mode as u32,
            field_rendering: cfg.field_rendering as u8,
            aa: cfg.sample_pattern.is_some() as u8,
            sample_pattern: cfg.sample_pattern.unwrap_or_default(),
            vfilter: cfg.v_filter,
        }
    }
}

impl From<&RenderConfig> for ffi::GXRModeObj {
    fn from(cfg: &RenderConfig) -> ffi::GXRModeObj {
        (*cfg).into()
    }
}

impl From<ffi::GXRModeObj> for RenderConfig {
    fn from(obj: ffi::GXRModeObj) -> Self {
        RenderConfig {
            video_fmt: VideoFmt::try_from(obj.viTVMode >> 2).unwrap(),
            scan_mode: ScanMode::try_from(obj.viTVMode & 0x3).unwrap(),
            fb_width: obj.fbWidth,
            efb_height: obj.efbHeight,
            xfb_height: obj.xfbHeight,
            vi_origin_x: obj.viXOrigin,
            vi_origin_y: obj.viYOrigin,
            vi_width: obj.viWidth,
            vi_height: obj.viHeight,
            xfb_mode: FieldMode::try_from(obj.xfbMode).unwrap(),
            field_rendering: obj.field_rendering != 0,
            sample_pattern: (obj.aa != 0).then_some(obj.sample_pattern),
            v_filter: obj.vfilter,
        }
    }
}

impl RenderConfig {
    /// Takes a given render mode and returns a version that is reduced in size to account for overscan.
    ///
    /// See [`ogc_sys::GX_AdjustForOverscan()`] for more.
    pub fn adjust_for_overscan(&self, hor: u16, ver: u16) -> Self {
        let mut rmin: ffi::GXRModeObj = self.into();
        let mut rmout = core::mem::MaybeUninit::uninit();
        // SAFETY: rmout can be uninit
        unsafe {
            ffi::GX_AdjustForOverscan(&mut rmin, rmout.as_mut_ptr(), hor, ver);
            rmout.assume_init().into()
        }
    }
}

impl Default for RenderConfig {
    fn default() -> Self {
        get_preferred_mode()
    }
}


/// Initializes the VIDEO subsystem. This must be called before using any other functions
/// in this module.
pub fn init() {
    unsafe { ffi::VIDEO_Init() }
}

/// Clears the framebuffer with the given render mode and YUYV color.
pub fn clear_framebuffer(rconf: &RenderConfig, fb: &mut Buf32, colour: u32) {
    let mut gxrmode: ffi::GXRModeObj = rconf.into();
    unsafe {
        ffi::VIDEO_ClearFrameBuffer(&mut gxrmode, fb.as_mut_ptr().cast(), colour);
    }
}

/// Returns the preferred render mode for the current configuration.
pub fn get_preferred_mode() -> RenderConfig {
    // SAFETY: passing NULL always gives us a valid pointer to valid static data.
    unsafe { *ffi::VIDEO_GetPreferredMode(ptr::null_mut()) }.into()
}

/// Configure the video screen with the given render mode object.
pub fn configure(render_config: &RenderConfig) {
    let mut gxrmode = render_config.into();
    unsafe {
        ffi::VIDEO_Configure(&mut gxrmode);
    }
}

/// Flush the shadow registers to the drivers video registers.
/// 
/// This must be called after using any of the following functions:
/// * `configure()`
/// * `set_next_framebuffer()`
/// * `set_black()`
pub fn flush() {
    unsafe { ffi::VIDEO_Flush() }
}

fn get_current_framebuffer() -> *mut c_void {
    unimplemented!()
}

/// Get current video line.
pub fn get_current_line() -> u32 {
    unsafe { ffi::VIDEO_GetCurrentLine() }
}

pub fn get_framebuffer_size(rmode: &RenderConfig) -> usize {
    let mut gxrmode = rmode.into();
    unsafe { ffi::VIDEO_GetFrameBufferSize(&mut gxrmode) as usize }
}

/// Get current configured video format, also called the TV mode.
pub fn get_video_fmt() -> VideoFmt {
    let mode = unsafe { ffi::VIDEO_GetCurrentTvMode() };
    VideoFmt::try_from(mode).unwrap()
}

/// Get the next video field.
pub fn get_next_field() -> VideoField {
    let next_field = unsafe { ffi::VIDEO_GetNextField() };
    VideoField::try_from(next_field).unwrap()
}

fn get_next_framebuffer() -> *mut c_void {
    unimplemented!()
}

/// Get the video scan mode.
pub fn get_scan_mode() -> ScanMode {
    let scan_mode = unsafe { ffi::VIDEO_GetVideoScanMode() };
    ScanMode::try_from(scan_mode).unwrap()
}

/// Check for a component cable. This returns true when a component cable (YPbPr) is
/// connected.
pub fn has_component_cable() -> bool {
    let component = unsafe { ffi::VIDEO_HaveComponentCable() };
    component == 1
}

/// Black out the VIDEO interface.
pub fn set_black(is_black: bool) {
    unsafe { ffi::VIDEO_SetBlack(is_black) }
}

/// Set the framebuffer for the next VI register update.
pub fn set_next_framebuffer(framebuffer: &Buf32) {
    unsafe {
        ffi::VIDEO_SetNextFramebuffer(framebuffer.as_ptr().cast_mut().cast());
    }
}

/// Set the right framebuffer for the next VI register update. This is used for 3D Gloves
/// for instance.
/// 
/// (No idea what libogc means by "3D gloves", and apparently this code has just Always
/// Been There.)
pub fn set_next_right_framebuffer(framebuffer: &Buf32) {
    unsafe {
        ffi::VIDEO_SetNextRightFramebuffer(framebuffer.as_ptr().cast_mut().cast());
    }
}

static POST_RETRACE_CB: AtomicPtr<fn(u32)> = AtomicPtr::null();

extern "C" fn post_retrace_callback_bridge(retrace_cnt: u32) {
    let cb_ptr = POST_RETRACE_CB.load(Ordering::Acquire);
    if ! cb_ptr.is_null() {
        // SAFETY: pointer is non-null and points to a valid rust function
        unsafe { (*cb_ptr)(retrace_cnt); }
    }
}

/// Sets the function to be called within the video interrupt handler after the VI
/// registers are updated.
/// 
/// Returns the previous callback function, if any.
pub fn set_post_retrace_callback(callback: RetraceCallback) -> RetraceCallback {
    let cb_ptr = match callback {
        None => {
            let _ = unsafe { ffi::VIDEO_SetPostRetraceCallback(None) };
            ptr::null_mut()
        }
        Some(mut f) => {
            let _ = unsafe { ffi::VIDEO_SetPostRetraceCallback(Some(post_retrace_callback_bridge)) };
            (&mut f) as *mut fn(u32)
        }
    };

    let prev_cb_ptr = POST_RETRACE_CB.swap(cb_ptr, Ordering::AcqRel);

    if prev_cb_ptr.is_null() {
        None
    } else {
        // SAFETY: pointer is non-null and always points to a valid rust function
        Some(unsafe { *prev_cb_ptr })
    }
}

static PRE_RETRACE_CB: AtomicPtr<fn(u32)> = AtomicPtr::null();

extern "C" fn pre_retrace_callback_bridge(retrace_cnt: u32) {
    let cb_ptr = PRE_RETRACE_CB.load(Ordering::Acquire);
    if ! cb_ptr.is_null() {
        // SAFETY: pointer is non-null and points to a valid rust function
        unsafe { (*cb_ptr)(retrace_cnt); }
    }
}

/// Sets the function to be called within the video interrupt handler before the VI
/// registers are updated.
/// 
/// Returns the previous callback function, if any.
pub fn set_pre_retrace_callback(callback: RetraceCallback) -> RetraceCallback {
    let cb_ptr = match callback {
        None => {
            let _ = unsafe { ffi::VIDEO_SetPreRetraceCallback(None) };
            ptr::null_mut()
        }
        Some(mut f) => {
            let _ = unsafe { ffi::VIDEO_SetPreRetraceCallback(Some(pre_retrace_callback_bridge)) };
            (&mut f) as *mut fn(u32)
        }
    };

    let prev_cb_ptr = PRE_RETRACE_CB.swap(cb_ptr, Ordering::AcqRel);

    if prev_cb_ptr.is_null() {
        None
    } else {
        // SAFETY: pointer is non-null and always points to a valid rust function
        Some(unsafe { *prev_cb_ptr })
    }
}

/// Wait on the next vertical retrace.
pub fn wait_vsync() {
    unsafe { ffi::VIDEO_WaitVSync() }
}
